"""R3f 差異部署：正式版 rk-r3b 原始碼 → insti_query_r1.py 換成 R3f（重試＋不快取部分失敗＋如實原因）、
app.py 排行榜快取條件加入「發行股數來源無失敗」。其餘檔案不動。
用法：python3 -B r3f_delta.py --src DIR --cand DIR
"""
import base64, gzip, hashlib, os, subprocess, sys
APP_OLD = "a3b5214daba69a1f"
INSTI_OLD = "3da9b6fe4649d648"
INSTI_NEW = "ae1786b8ebaa819c3da89d19524bace68e7ac4441d0346f1d4070435a05d501a"
APP_A = '                        "ok": bool(day0) and len(stars) >= 60,'
APP_B = '                        "ok": bool(day0) and len(stars) >= 60 and not ((getattr(_rkr3_q, "_R3_SHARES", {}) or {}).get("fail")),'
INSTI_GZ = ""
sha = lambda b: hashlib.sha256(b).hexdigest()
def need(c, m):
    if not c:
        print("[R3F_STOP]", m); sys.exit(1)
a = sys.argv[1:]
src, cand = a[a.index("--src") + 1], a[a.index("--cand") + 1]
app_b, ins_b = open(os.path.join(src, "app.py"), "rb").read(), open(os.path.join(src, "insti_query_r1.py"), "rb").read()
need(sha(app_b).startswith(APP_OLD), "app.py 不是正式版 rk-r3b " + sha(app_b)[:16])
need(sha(ins_b).startswith(INSTI_OLD), "insti 不是正式版 R3e " + sha(ins_b)[:16])
new_ins = gzip.decompress(base64.b64decode(INSTI_GZ))
need(sha(new_ins) == INSTI_NEW, "內嵌 R3f 檔 SHA 不符")
app_t = app_b.decode("utf-8")
need(app_t.count(APP_A) == 1, "app.py 錨點不唯一")
new_app = app_t.replace(APP_A, APP_B).encode("utf-8")
compile(new_app, "app.py", "exec"); compile(new_ins, "insti_query_r1.py", "exec")
need(not os.path.exists(cand), "候選目錄已存在")
os.makedirs(os.path.dirname(cand), exist_ok=True)
subprocess.run(["cp", "-al", src, cand], check=True)
for name, data in (("app.py", new_app), ("insti_query_r1.py", new_ins)):
    tmp = os.path.join(cand, "." + name + ".tmp")
    open(tmp, "wb").write(data)
    os.replace(tmp, os.path.join(cand, name))
    need(os.stat(os.path.join(cand, name)).st_nlink == 1, name + " 仍是硬連結")
need(sha(open(os.path.join(src, "app.py"), "rb").read()) == sha(app_b), "基底被改動")
print(f"[R3F_PATCHED] candidate={cand} app={sha(new_app)[:16]} insti={sha(new_ins)[:16]}")
